<?php
namespace App\Services;
use RuntimeException;
class LegacyMediaReader { public function path(string $legacyPath):string{$relative=ltrim((string)parse_url($legacyPath,PHP_URL_PATH),'/');$relative=preg_replace('#^wp-conten(?:t|u)/uploads/#','',$relative);foreach(array_filter(array_merge([(string)config('legacy-media.uploads_path')],config('legacy-media.additional_uploads_paths',[]))) as $root){$base=realpath($root);$file=$base?realpath($base.'/'.$relative):false;if($file&&str_starts_with($file,$base.DIRECTORY_SEPARATOR)&&is_readable($file))return $file;}throw new RuntimeException('Legacy media path is unavailable locally.');} public function inspect(string $legacyPath):array{$file=$this->path($legacyPath);$size=@getimagesize($file);return ['source'=>$file,'bytes'=>filesize($file),'checksum'=>hash_file('sha256',$file),'mime'=>$size['mime']??mime_content_type($file),'width'=>$size[0]??null,'height'=>$size[1]??null];} public function copyTo(string $legacyPath,string $destination):array{$data=$this->inspect($legacyPath);if(!copy($data['source'],$destination))throw new RuntimeException('V2 copy failed.');return $data;} }
